using System.Text.Json;
using Avalonia;
using Avalonia.Media.Imaging;

namespace Legend.Playable.Ui;

/// <summary>
/// Original 8-direction sheet (5 stored directions, the other three are mirrors).
/// Generated by tools/gen_mir_sheet.py. Not official Mir WIL/WZL art.
/// </summary>
public sealed class MirSheet
{
    public Bitmap Bitmap { get; }
    public int FrameW { get; }
    public int FrameH { get; }
    public int FramesPerDir { get; }
    public IReadOnlyList<string> Actions { get; }
    public IReadOnlyDictionary<string, int> ActionFrames { get; }
    public IReadOnlyList<string> Actors { get; }
    public int TileSize { get; }
    public int TileY { get; }
    public IReadOnlyList<string> Tiles { get; }
    public int FxY { get; }
    public IReadOnlyList<string> Fx { get; }
    public int FxFrames { get; }
    public int FxSize { get; }

    private MirSheet(Bitmap bitmap, JsonElement root)
    {
        Bitmap = bitmap;
        FrameW = root.GetProperty("frameW").GetInt32();
        FrameH = root.GetProperty("frameH").GetInt32();
        FramesPerDir = root.GetProperty("framesPerDir").GetInt32();
        Actions = ReadStrings(root.GetProperty("actions"));
        var frames = new Dictionary<string, int>(StringComparer.Ordinal);
        foreach (var prop in root.GetProperty("actionFrames").EnumerateObject())
            frames[prop.Name] = prop.Value.GetInt32();
        ActionFrames = frames;
        Actors = ReadStrings(root.GetProperty("actors"));
        TileSize = root.GetProperty("tileSize").GetInt32();
        TileY = root.GetProperty("tileY").GetInt32();
        Tiles = ReadStrings(root.GetProperty("tiles"));
        FxY = root.GetProperty("fxY").GetInt32();
        Fx = ReadStrings(root.GetProperty("fx"));
        FxFrames = root.GetProperty("fxFrames").GetInt32();
        FxSize = root.GetProperty("fxSize").GetInt32();
    }

    public static MirSheet? TryLoad(System.Reflection.Assembly assembly)
    {
        using var png = assembly.GetManifestResourceStream("assets.atlas.png");
        using var json = assembly.GetManifestResourceStream("assets.atlas.json");
        if (png == null || json == null)
            return null;
        using var reader = new StreamReader(json);
        using var doc = JsonDocument.Parse(reader.ReadToEnd());
        return new MirSheet(new Bitmap(png), doc.RootElement.Clone());
    }

    public bool TrySprite(string actor, string action, int direction, int frame, out Rect src, out bool flip)
    {
        src = default;
        flip = false;
        int actorIndex = IndexOf(Actors, actor);
        int actionIndex = IndexOf(Actions, action);
        if (actorIndex < 0 || actionIndex < 0)
            return false;
        int dir = NormalizeDir(direction, out flip);
        int count = ActionFrames.TryGetValue(action, out int n) ? n : 1;
        int slot = Math.Clamp(frame, 0, Math.Max(0, count - 1));
        int col = dir * FramesPerDir + slot;
        int row = actorIndex * Actions.Count + actionIndex;
        src = new Rect(col * FrameW, row * FrameH, FrameW, FrameH);
        return true;
    }

    public bool TryTile(string name, out Rect src)
    {
        src = default;
        int index = IndexOf(Tiles, name);
        if (index < 0)
            return false;
        src = new Rect(index * TileSize, TileY, TileSize, TileSize);
        return true;
    }

    public bool TryFx(string name, int frame, out Rect src)
    {
        src = default;
        int index = IndexOf(Fx, name);
        if (index < 0)
            return false;
        int slot = Math.Clamp(frame, 0, Math.Max(0, FxFrames - 1));
        src = new Rect((index * FxFrames + slot) * FxSize, FxY, FxSize, FxSize);
        return true;
    }

    public static string ActorId(World.ActorView actor)
    {
        string template = actor.TemplateId ?? "";
        if (actor.Kind == Legend.Contracts.Proto.EntityKind.EntityNpc)
            return "npc";
        if (actor.Kind == Legend.Contracts.Proto.EntityKind.EntityPet || template.Contains("pet", StringComparison.OrdinalIgnoreCase) || template.Contains("wolf", StringComparison.OrdinalIgnoreCase))
            return "wolf";
        if (actor.Kind == Legend.Contracts.Proto.EntityKind.EntityMonster)
        {
            if (template.Contains("slime", StringComparison.OrdinalIgnoreCase)) return "slime";
            if (template.Contains("boar", StringComparison.OrdinalIgnoreCase)) return "boar";
            if (template.Contains("bone", StringComparison.OrdinalIgnoreCase)) return "bone";
            if (template.Contains("crawler", StringComparison.OrdinalIgnoreCase)) return "crawler";
            if (template.Contains("wraith", StringComparison.OrdinalIgnoreCase)) return "wraith";
            if (template.Contains("dragon", StringComparison.OrdinalIgnoreCase)) return "dragon";
            if (template.Contains("gate", StringComparison.OrdinalIgnoreCase)) return "gate";
            if (template.Contains("wall", StringComparison.OrdinalIgnoreCase)) return "wall";
            if (template.Contains("flag", StringComparison.OrdinalIgnoreCase)) return "flag";
            return "boar";
        }
        bool female = string.Equals(actor.Gender, "f", StringComparison.OrdinalIgnoreCase);
        if (!string.IsNullOrEmpty(actor.FashionId))
            return female ? "fashion_f" : "fashion_m";
        string cls = actor.ClassId ?? "";
        string gender = female ? "f" : "m";
        if (cls.Contains("mage", StringComparison.OrdinalIgnoreCase)) return "mage_" + gender;
        if (cls.Contains("tao", StringComparison.OrdinalIgnoreCase)) return "tao_" + gender;
        return "war_" + gender;
    }

    public static int FrameIndex(string action, double phase, double poseLock)
    {
        int count = action switch
        {
            "idle" => 4,
            "hit" => 3,
            "death" => 4,
            _ => 6
        };
        if (action is "attack" or "cast" or "hit" or "death")
        {
            double span = action switch
            {
                "cast" => 0.48,
                "hit" => 0.22,
                "death" => 1.2,
                _ => 0.42
            };
            _ = poseLock;
            return Math.Clamp((int)(phase / span * count), 0, count - 1);
        }
        double fps = action switch
        {
            "run" => 12,
            "walk" => 8,
            _ => 4
        };
        int loop = (int)(phase * fps) % count;
        return loop < 0 ? 0 : loop;
    }

    private static int NormalizeDir(int direction, out bool flip)
    {
        int d = ((direction % 8) + 8) % 8;
        flip = d is 5 or 6 or 7;
        return d switch
        {
            5 => 3,
            6 => 2,
            7 => 1,
            _ => d
        };
    }

    private static int IndexOf(IReadOnlyList<string> list, string name)
    {
        for (int i = 0; i < list.Count; i++)
        {
            if (string.Equals(list[i], name, StringComparison.OrdinalIgnoreCase))
                return i;
        }
        return -1;
    }

    private static List<string> ReadStrings(JsonElement array)
    {
        var list = new List<string>();
        foreach (var item in array.EnumerateArray())
        {
            string? s = item.GetString();
            if (!string.IsNullOrEmpty(s))
                list.Add(s);
        }
        return list;
    }
}
